package fixture

import "testing"

func TestIsPalindrome(t *testing.T) {
	if !IsPalindrome("racecar") {
		t.Fatal("racecar should be a palindrome")
	}
	if IsPalindrome("abca") {
		t.Fatal("abca should not be a palindrome")
	}
	if !IsPalindrome("a") {
		t.Fatal("a should be a palindrome")
	}
}
